function parseInscriptionProtectionServerEnabled(
  value: string,
): boolean | undefined {
  try {
    const parsed = JSON.parse(value) as { value?: unknown };
    return typeof parsed?.value === 'boolean' ? parsed.value : undefined;
  } catch {
    return undefined;
  }
}

